def main():
    out_dir = os.path.join(os.path.dirname(__file__), "data")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "apna_college_sheet.json")

    total_q = 0
    qid = 1
    processed_data = {}
    for cat, qs in SHEET_DATA.items():
        processed_data[cat] = []
        for q in qs:
            slug = slugify(q["title"])
            aliases = [slugify(a) for a in q.get("aliases", [])]
            if slug not in aliases:
                aliases.append(slug)
            
            # Form search/practice links
            search_query = f"{q['title']} LeetCode GeeksforGeeks".replace(' ', '+')
            problem_url = f"https://www.google.com/search?q={search_query}"
            
            processed_data[cat].append({
                "id": qid,
                "category": cat,
                "title": q["title"],
                "slug": slug,
                "companies": q["companies"],
                "remarks": q["remarks"],
                "aliases": aliases,
                "problem_url": problem_url
            })
            qid += 1
            total_q += 1

    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(processed_data, f, indent=2)

    print(f"Successfully generated {out_path}")
    print(f"Total categories: {len(processed_data)}, Total questions: {total_q}")

if __name__ == "__main__":
    main()
